      hu: ["Száraz folyómedrek", "Félsivatag", "Homokkő"],
      ro: ["Albii de râu uscate", "Semideșert", "Gresie"],
      en: ["Dry riverbeds", "Semi-desert", "Sandstone"],
      es: ["Lechos de ríos secos", "Semidesierto", "Arenisca"],
